const rows = episode.steps.map(s => {
  const text = s.answer || '';
  let verdict;
  if (s.abstain) {
    const fabricated = /\d{1,2}\s*月\s*\d{1,2}\s*日|某公司|有限公司|公司叫/.test(text);
    const hasHedge = /(没有?提到|没说过|不知道|不记得|没有告诉|没说过具体)/.test(text);
    verdict = fabricated ? 'fail_fabricated' : (hasHedge ? 'pass' : 'pass_weak');
  } else {
    const hits = (s.expect || []).filter(kw => text.includes(kw));
    const forbids = /forbid/ in s ? [] : [];
    verdict = hits.length === (s.expect || []).length ? 'pass' : (hits.length ? 'partial' : 'fail');
  }
  return { ask: s.ask, category: s.category, verdict, answer: text.slice(0, 140) };
});
